"""Guards for the README diagrams (SVG images generated by assets/diagrams/build_diagrams.py)."""
from __future__ import annotations

import importlib.util
import re
import subprocess
import sys
import xml.etree.ElementTree as ET

import pytest

from conftest import REPO_ROOT

README = REPO_ROOT / "README.md"
DIAGRAMS = REPO_ROOT / "assets" / "diagrams"
SCRIPT = DIAGRAMS / "build_diagrams.py"
SVGS = ["paper-pipeline.svg", "skills.svg"]


def _load_script():
    spec = importlib.util.spec_from_file_location("build_diagrams", SCRIPT)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_readme_has_no_mermaid_fence():
    assert "```mermaid" not in README.read_text(encoding="utf-8")


def test_readme_relative_images_exist():
    text = README.read_text(encoding="utf-8")
    paths = re.findall(r"!\[[^\]]*\]\(([^)\s]+)", text) + re.findall(
        r"<img[^>]+src=[\"']([^\"']+)[\"']", text
    )
    assert paths, "expected the README to reference images"
    for p in paths:
        if p.startswith(("http://", "https://")):
            continue
        assert (REPO_ROOT / p).is_file(), f"README image missing: {p}"


def test_generated_svgs_are_current():
    r = subprocess.run([sys.executable, str(SCRIPT), "--check"], capture_output=True, text=True)
    assert r.returncode == 0, r.stdout + r.stderr


def test_skills_diagram_matches_skill_directories():
    mod = _load_script()
    drawn = {s.lstrip("/") for _, skills in mod.SKILL_GROUPS for s in skills}
    on_disk = {p.name for p in (REPO_ROOT / ".claude" / "skills").iterdir() if p.is_dir()}
    assert drawn == on_disk
    assert mod.skill_count() == len(on_disk)
    title = ET.parse(DIAGRAMS / "skills.svg").getroot().find("{http://www.w3.org/2000/svg}title").text
    assert str(len(on_disk)) in title.split()


@pytest.mark.parametrize("name", SVGS)
def test_svg_is_well_formed_and_self_contained(name):
    raw = (DIAGRAMS / name).read_text(encoding="utf-8")
    root = ET.fromstring(raw)
    assert root.get("viewBox")
    assert "<script" not in raw.lower()
    assert "foreignobject" not in raw.lower()
    for el in root.iter():
        for key, val in el.attrib.items():
            if key.endswith("href"):
                assert not re.match(r"(?i)(https?:)?//", val), f"external href in {name}: {val}"
